    p=Pipr(home=home)
    for a in actions:
        if isinstance(a,str): p.text(a)
        else: p.send(*a if isinstance(a,tuple) else [a])
        print(name,"after",a, hf(home))
    p.show("final"); bm(home)
    try: p.kill()
    except: pass

