{"command":"cat > /tmp/h2.py << 'PY'
import sys; sys.path.insert(0,'/tmp')
from h import Pipr
import subprocess, os, shutil, time

def make_home(name, config=None, history=None, bookmarks=None):
    home=f"/tmp/cfg_{name}"
    shutil.rmtree(home, ignore_errors=True)
    os.makedirs(home+"/.config/pipr", exist_ok=True)
    if config is not None:
        open(home+"/.config/pipr/pipr.toml","w").write(config)
    if history is not None:
        open(home+"/.config/pipr/history","w").write(history)
    if bookmarks is not None:
        open(home+"/.config/pipr/bookmarks","w").write(bookmarks)
    return home

def snap(p, title=""):
    lines=[l.rstrip() for l in p.cap().splitlines()]
    print(f"---{title}---")
    for i,l in enumerate(lines):
        if l.strip(): print(f"{i:02d}|{l}")
    return lines

def esc_snap(p, title=""):
    print(f"---{title} esc---")
    for i,l in enumerate(p.cap(esc=True).splitlines()):
        if l.strip(): print(f"{i:02d}|{l!r}")

def run(name, config=None, actions=None, args="--no-isolation", history=None, bookmarks=None, w=80,h=24):
    home=make_home(name, config, history, bookmarks)
    p=Pipr(home=home, args=args, w=w, h=h)
    snap(p, f"{name} initial")
    if actions:
        for a in actions:
            if isinstance(a, tuple):
                if a[0]=="text": p.text(a[1])
                elif a[0]=="sleep": import time; time.sleep(a[1])
                elif a[0]=="snap": snap(p, a[1]); continue
            else:
                p.send(a)
            snap(p, f"{name} after {a}")
    p.kill()
    return home
PY
