from h2 import *
import subprocess
def cur(p):
    r=subprocess.run(["tmux","display-message","-t",p.session,"-p","#{cursor_x},#{cursor_y}"],capture_output=True,text=True)
    return r.stdout.strip()
def one(name, init, keys):
    home=make_home("k2","autoeval_mode_default=true\n")
