fn get_string_table(table: &toml::value::Table, name: &str) -> HashMap<String, String> {
    let mut result = HashMap::new();
    if let Some(Value::Table(map)) = table.get(name) {
        for (key, value) in map {
            match value_to_string(value) {
                Some(value) => {
                    result.insert(key.clone(), value);
                }
                None => return HashMap::new(),
            }
        }
    }
    result
}

fn get_string_array(table: &toml::value::Table, name: &str) -> Option<Vec<String>> {
    if let Some(Value::Array(items)) = table.get(name) {
        let mut result = Vec::new();
        for item in items {
            result.push(value_to_string(item)?);
        }
        Some(result)
    } else {
        None
    }
}

fn relative_display_path(path: &Path) -> String {
    let absolute_path = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    };
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/"));
    let path_components: Vec<_> = absolute_path.components().collect();
    let cwd_components: Vec<_> = cwd.components().collect();
    let mut shared = 0;
    while shared < path_components.len()
        && shared < cwd_components.len()
        && path_components[shared] == cwd_components[shared]
    {
        shared += 1;
    }
    let mut relative = PathBuf::new();
    for _ in shared..cwd_components.len() {
        relative.push("..");
    }
    for component in &path_components[shared..] {
        relative.push(component.as_os_str());
    }
    let text = relative.display().to_string();
    if text.is_empty() {
        path.display().to_string()
    } else {
        text
    }
}

fn load_config_value(path: &Path) -> Result<Value, ConfigError> {
    if !path.is_file() {
        return Err(ConfigError(format!(
            "configuration file \"{}\" not found",
            path.display()
        )));
    }
    let contents = fs::read_to_string(path).map_err(|error| ConfigError(error.to_string()))?;
    let value: Value = toml::from_str(&contents).map_err(|error| {
        ConfigError(format!(
            "{}\n in {}",
            error.to_string().trim_end(),
            relative_display_path(path)
        ))
    })?;
    Ok(value)
}

impl PiprConfig {
    pub fn new(config_directory: &Path) -> Self {
        let config_file_path = config_directory.join("pipr.toml");
        std::fs::create_dir_all(config_directory).unwrap();
        if !config_file_path.exists() {
            write_default_config_file(&config_file_path);
        }
        let loaded_value =
            load_config_value(&config_file_path).unwrap();
        let empty_table = toml::value::Table::new();
        let table = match &loaded_value {
            Value::Table(table) => table,
            _ => &empty_table,
        };
        PiprConfig {
            finish_hook: table.get("finish_hook").and_then(value_to_string),
            paranoid_history_mode_default: get_bool(
                table,
                "paranoid_history_mode_default",
                false,
            ),
            autoeval_mode_default: get_bool(table, "autoeval_mode_default", false),
            history_size: get_integer(table, "history_size", 500),
            cmdlist_always_show_preview: get_bool(
                table,
                "cmdlist_always_show_preview",
                false,
            ),
            cmd_timeout_millis: get_integer(table, "cmd_timeout_millis", 2000),
            highlighting_enabled: get_bool(table, "highlighting_enabled", true),
            eval_environment: get_string_array(table, "eval_environment")
