# Monkey-patch Pipr class to use original binary by replacing /workspace/executable in __init__ code? Easier duplicate class
import subprocess, time, os, shutil
class Pipr:
    def __init__(self, session="pipr", args="--no-isolation", home="/tmp/fakehome1", w=80,h=24, extra_env=""):
        self.session=session
