    fn set(&mut self, from: usize, to: usize, color: (u8, u8, u8)) {
        for slot in self.colors.iter_mut().take(to).skip(from) {
            *slot = color;
        }
    }

    fn peek(&self, offset: usize) -> Option<char> {
        self.chars.get(self.index + offset).copied()
    }

    fn is_word_char(character: char) -> bool {
        !character.is_whitespace()
            && !matches!(
                character,
                '|' | '&' | ';' | '(' | ')' | '<' | '>' | '\'' | '"' | '`' | '$' | '\\'
            )
    }

    fn scan_variable(&mut self, inside_double: bool) {
        let start = self.index;
        // The dollar sign itself stays in the surrounding (usually default) colour.
        self.index += 1;
        if self.peek(0) == Some('(') {
            self.index += 1;
            self.contexts.push(Context::Substitution);
            self.expect_command = true;
            self.current_command.clear();
            return;
        }
        if self.peek(0) == Some('{') {
            self.index += 1;
            if inside_double {
                if self.index < self.chars.len() {
                    self.colors[self.index - 1] = STRING;
                }
            }
            let name_start = self.index;
            while let Some(character) = self.peek(0) {
                if character.is_alphanumeric() || character == '_' {
                    self.index += 1;
                } else {
                    break;
                }
            }
            self.set(name_start, self.index, VARIABLE);
            // Operators such as :- are default, a following default value is
            // green in the source theme in string contexts and default outside.
            while let Some(character) = self.peek(0) {
                if character == '}' {
                    if inside_double {
                        self.colors[self.index] = STRING;
                    }
                    self.index += 1;
                    break;
                } else if character == '$' {
                    self.scan_variable(inside_double);
                } else {
                    if inside_double
                        && !matches!(character, ':' | '-' | '=' | '+' | '?' | '%')
                    {
                        self.colors[self.index] = STRING;
                    }
                    self.index += 1;
                }
            }
            let _ = start;
            return;
        }
        let name_start = self.index;
        if let Some(character) = self.peek(0) {
            if character.is_alphabetic() || character == '_' {
                while let Some(next) = self.peek(0) {
                    if next.is_alphanumeric() || next == '_' {
                        self.index += 1;
                    } else {
                        break;
                    }
                }
            } else if character.is_ascii_digit()
                || matches!(character, '@' | '*' | '#' | '?' | '$' | '!' | '-' )
            {
                self.index += 1;
            }
        }
        self.set(name_start, self.index, VARIABLE);
    }

    fn scan_single_quote(&mut self, ansi_c_quote: bool) {
        // Opening delimiter is default.
        self.index += 1;
        while let Some(character) = self.peek(0) {
            if character == '\'' {
                self.index += 1;
                return;
            }
            if ansi_c_quote && character == '\\' {
                let start = self.index;
                self.index += 1;
                if self.peek(0).is_some() && self.peek(0) != Some('\n') {
                    self.index += 1;
                }
                self.set(start, self.index, BUILTIN);
                continue;
            }
            self.colors[self.index] = STRING;
            self.index += 1;
        }
    }

    fn scan_double_quote(&mut self) {
        self.index += 1;
        while let Some(character) = self.peek(0) {
            if character == '"' {
                self.index += 1;
                return;
            }
            if character == '$' {
                self.colors[self.index] = DEFAULT;
                self.scan_variable(true);
                continue;
            }
            if character == '\\' {
                let next = self.peek(1);
                if matches!(next, Some('$' | '"' | '\\' | '`')) {
                    let start = self.index;
                    self.index += 2;
                    self.set(start, self.index, BUILTIN);
                    continue;
                }
                self.colors[self.index] = STRING;
                self.index += 1;
                continue;
            }
            if character == '`' {
                self.index += 1;
                self.contexts.push(Context::Backtick);
                self.expect_command = true;
                self.scan_normal_until_context_end();
                continue;
            }
            self.colors[self.index] = STRING;
            self.index += 1;
        }
    }

    fn classify_and_scan_word(&mut self) {
        let start = self.index;
        while let Some(character) = self.peek(0) {
            if Self::is_word_char(character) {
                self.index += 1;
            } else {
                break;
            }
        }
        let word: String = self.chars[start..self.index].iter().collect();
        if word.is_empty() {
            return;
        }

        // Assignment in command position or after export-like builtins.
        if self.expect_command || self.export_like {
            if let Some(equal) = word.find('=') {
                let name = &word[..equal];
                if !name.is_empty()
                    && name
                        .chars()
                        .all(|character| character.is_alphanumeric() || character == '_')
                    && name
                        .chars()
                        .next()
                        .map(|character| character.is_alphabetic() || character == '_')
                        .unwrap_or(false)
                {
                    self.set(start, start + equal, VARIABLE);
                    self.set(start + equal + 1, self.index, STRING);
                    if self.expect_command {
                        // Still expecting the actual command after assignments.
                        return;
                    } else {
                        return;
                    }
                }
            }
        }

        if self.after_for == 1 {
            self.after_for = 2;
            return;
        }
        if self.after_for == 2 && word == "in" {
            self.set(start, self.index, KEYWORD);
            self.after_for = 0;
            self.expect_command = false;
            return;
        }
        if self.after_case == 1 {
            self.after_case = 2;
            return;
        }
        if self.after_case == 2 && word == "in" {
            self.set(start, self.index, KEYWORD);
            self.after_case = 0;
            self.expect_command = false;
            return;
        }

        if self.expect_command {
            if word == "for" {
                self.set(start, self.index, KEYWORD);
                self.after_for = 1;
                self.expect_command = false;
                self.current_command = word;
                return;
            }
            if word == "case" {
                self.set(start, self.index, KEYWORD);
                self.after_case = 1;
                self.expect_command = false;
                self.in_case = true;
                self.current_command = word;
                return;
            }
            if self.in_case && word == "esac" {
                self.set(start, self.index, KEYWORD);
                self.in_case = false;
                self.expect_command = false;
                self.current_command = word;
                return;
            }
            if KEYWORDS.contains(&word.as_str()) {
                self.set(start, self.index, KEYWORD);
                self.export_like = matches!(
                    word.as_str(),
                    "export" | "declare" | "local" | "readonly" | "typeset"
                );
                if matches!(
                    word.as_str(),
                    "if" | "then" | "else" | "elif" | "while" | "until" | "do"
                ) {
                    self.expect_command = true;
                } else {
                    self.expect_command = false;
                }
                self.current_command = word;
                return;
            }
            if (word == "done" || word == "fi") && start == 0 {
                self.set(start, self.index, KEYWORD);
                self.expect_command = false;
                self.current_command = word;
                return;
            }
            // Square bracket commands are built-ins and handled by the list.
            if BUILTINS.contains(&word.as_str()) {
                self.set(start, self.index, BUILTIN);
            } else {
                self.set(start, self.index, COMMAND);
            }
            self.current_command = word.clone();
            self.export_like = false;
            self.expect_command = false;
            return;
        }

        // Arguments.
        if self.export_like {
            let has_dash = word.starts_with('-');
            if !has_dash {
                self.set(start, self.index, VARIABLE);
            }
            return;
        }
        if word.starts_with('-')
            && word.len() > 1
            && word != "--"
            && word[1..]
                .chars()
                .next()
                .map(|character| character.is_alphanumeric())
                .unwrap_or(false)
        {
            let is_option = if BUILTINS.contains(&self.current_command.as_str()) {
                if self.current_command == "echo" {
                    word.starts_with('-')
                        && word[1..]
                            .chars()
                            .all(|character| matches!(character, 'n' | 'e' | 'E'))
                        && word.len() > 1
                } else if self.current_command == "[" || self.current_command == "[[" {
                    true
                } else {
                    false
                }
            } else {
                true
            };
            if is_option {
                self.set(start, self.index, VARIABLE);
                if !BUILTINS.contains(&self.current_command.as_str()) {
                    // Generic commands include the preceding blank in the
                    // option scope.
                    if start > 0 && self.chars[start - 1] == ' ' {
                        self.colors[start - 1] = VARIABLE;
                    }
                }
                return;
            }
        }
        if word.chars().all(|character| character.is_ascii_digit())
            && matches!(self.peek(0), Some('<' | '>'))
        {
            self.set(start, self.index, NUMBER);
            return;
        }
        // Path-like home marker and glob brackets in otherwise default text.
        for (offset, character) in word.chars().enumerate() {
            match character {
                '~' if offset == 0 => self.colors[start + offset] = VARIABLE,
                '[' | ']' => self.colors[start + offset] = KEYWORD,
                _ => {}
            }
        }
    }

    fn scan_normal_until_context_end(&mut self) {
        while let Some(character) = self.peek(0) {
            // Terminators for pushed contexts.
            if let Some(context) = self.contexts.last().copied() {
                if context == Context::Backtick && character == '`' {
                    self.contexts.pop();
                    self.index += 1;
                    self.expect_command = false;
                    return;
                }
                if context == Context::Substitution && character == ')' {
                    self.contexts.pop();
                    self.index += 1;
                    self.expect_command = false;
                    return;
                }
            }
            if character == '\n' {
                self.index += 1;
                self.expect_command = true;
                self.current_command.clear();
                self.export_like = false;
                continue;
            }
            if character.is_whitespace() {
                self.index += 1;
                continue;
            }
            if character == '#'
                && (self.index == 0
                    || self.chars[self.index - 1].is_whitespace()
                    || matches!(self.chars[self.index - 1], ';' | '|' | '&' | '('))
            {
                while let Some(next) = self.peek(0) {
                    if next == '\n' {
                        break;
                    }
                    self.colors[self.index] = COMMENT;
                    self.index += 1;
                }
                continue;
            }
            if character == '\'' {
                self.scan_single_quote(false);
                self.expect_command = false;
                continue;
            }
            if character == '"' {
                self.scan_double_quote();
                self.expect_command = false;
                continue;
            }
            if character == '$' {
                if self.peek(1) == Some('\'') {
                    // ANSI-C quoted string $'...'
                    self.index += 1; // dollar, default
                    self.scan_single_quote(true);
                    self.expect_command = false;
                    continue;
                }
                self.scan_variable(false);
                self.expect_command = false;
                continue;
            }
            if character == '`' {
                self.index += 1;
                self.contexts.push(Context::Backtick);
                self.expect_command = true;
                continue;
            }
            if character == '\\' {
                let start = self.index;
                self.index += 1;
                if let Some(next) = self.peek(0) {
                    if next != '\n' {
                        self.index += 1;
                        self.set(start, self.index, BUILTIN);
                    }
                }
                continue;
            }
            if matches!(character, '|' | ';') {
                self.index += 1;
                if character == '|' && self.peek(0) == Some('|') {
                    self.index += 1;
                }
                self.expect_command = true;
                self.current_command.clear();
                self.export_like = false;
                continue;
            }
            if character == '&' {
                self.index += 1;
                if self.peek(0) == Some('&') {
                    self.index += 1;
                }
                self.expect_command = true;
                self.current_command.clear();
                continue;
            }
            if character == '(' {
                self.index += 1;
                self.expect_command = true;
                continue;
            }
            if character == ')' {
                self.index += 1;
                if self.in_case {
                    self.colors[self.index - 1] = KEYWORD;
                }
                self.expect_command = true;
                continue;
            }
            if matches!(character, '<' | '>') {
                self.index += 1;
                self.expect_command = false;
                continue;
            }
            if Self::is_word_char(character) {
                self.classify_and_scan_word();
                continue;
            }
            self.index += 1;
        }
    }
}

pub fn highlighted_lines(text: &str, enabled: bool) -> Vec<Line<'static>> {
    let textual_lines: Vec<&str> = text.split('\n').collect();
    if !enabled {
        return textual_lines
            .into_iter()
            .map(|line| Line::from(line.to_string()))
            .collect();
    }
    let chars: Vec<char> = text.chars().collect();
    let mut scanner = Scanner {
        colors: vec![DEFAULT; chars.len()],
        chars,
        index: 0,
        expect_command: true,
        current_command: String::new(),
        in_case: false,
        after_for: 0,
        after_case: 0,
        export_like: false,
        contexts: Vec::new(),
    };
    scanner.scan_normal_until_context_end();

    let mut lines: Vec<Line> = Vec::new();
    let mut spans: Vec<Span> = Vec::new();
    let mut current_text = String::new();
    let mut current_color = scanner.colors.first().copied().unwrap_or(DEFAULT);
    let char_count = scanner.chars.len();
    for index in 0..=char_count {
        if index == char_count || scanner.chars[index] == '\n' {
            if !current_text.is_empty() {
                spans.push(Span::styled(current_text.clone(), style(current_color)));
                current_text.clear();
            }
            lines.push(Line::from(spans));
            spans = Vec::new();
            if index < char_count {
                current_color = scanner.colors.get(index + 1).copied().unwrap_or(DEFAULT);
            }
            continue;
        }
        let color = scanner.colors[index];
        if color != current_color {
            if !current_text.is_empty() {
                spans.push(Span::styled(current_text.clone(), style(current_color)));
                current_text.clear();
            }
            current_color = color;
        }
        current_text.push(scanner.chars[index]);
    }
    lines
}
RS
"}

