                spans.push(Span::styled(current_text.clone(), style(current_color)));
                current_text.clear();
            }
            lines.push(Line::from(spans));
            spans = Vec::new();
            if index < char_count {
                current_color = scanner.colors.get(index + 1).copied().unwrap_or(DEFAULT);
            }
            continue;
        }
        let color = scanner.colors[index];
        if color != current_color {
            if !current_text.is_empty() {
                spans.push(Span::styled(current_text.clone(), style(current_color)));
                current_text.clear();
            }
            current_color = color;
        }
        current_text.push(scanner.chars[index]);
    }
    lines
}
RS
