#[derive(Clone, Debug)]
pub struct TextField {
    pub lines: Vec<String>,
    pub cursor_line: usize,
    pub cursor_column: usize, // in characters, within the current line
}

impl Default for TextField {
    fn default() -> Self {
        TextField {
            lines: vec![String::new()],
            cursor_line: 0,
            cursor_column: 0,
        }
    }
}

pub fn string_to_lines(text: &str) -> Vec<String> {
    let mut lines: Vec<String> = text.lines().map(|line| line.to_string()).collect();
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

impl TextField {
    pub fn command_string(&self) -> String {
        self.lines.join("\n")
    }

    pub fn set_command(&mut self, text: &str) {
        self.lines = string_to_lines(text);
        self.cursor_line = self.lines.len() - 1;
        self.cursor_column = self.current_line().chars().count();
    }

    pub fn current_line(&self) -> &str {
        &self.lines[self.cursor_line]
    }

    fn current_line_length(&self) -> usize {
        self.current_line().chars().count()
    }

    fn byte_index(&self, line_index: usize, column: usize) -> usize {
        let line = &self.lines[line_index];
        if column >= line.chars().count() {
            line.len()
        } else {
            line.char_indices()
                .nth(column)
                .map(|(index, _)| index)
                .unwrap_or(line.len())
        }
    }

    pub fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.cursor_line = 0;
        self.cursor_column = 0;
    }

    pub fn insert_char(&mut self, character: char) {
        let byte = self.byte_index(self.cursor_line, self.cursor_column);
        self.lines[self.cursor_line].insert(byte, character);
        self.cursor_column += 1;
    }

    pub fn insert_text(&mut self, text: &str) {
        let byte = self.byte_index(self.cursor_line, self.cursor_column);
        self.lines[self.cursor_line].insert_str(byte, text);
        self.cursor_column += text.chars().count();
    }

    pub fn insert_snippet_text(&mut self, text: &str, cursor_offset: usize) {
        let start_column = self.cursor_column;
        let byte = self.byte_index(self.cursor_line, self.cursor_column);
        self.lines[self.cursor_line].insert_str(byte, text);
        self.cursor_column = start_column + cursor_offset;
    }

    pub fn backspace(&mut self) -> bool {
        if self.cursor_column > 0 {
            let byte = self.byte_index(self.cursor_line, self.cursor_column - 1);
            self.lines[self.cursor_line].remove(byte);
            self.cursor_column -= 1;
            true
        } else if self.cursor_line > 0 {
            let current = self.lines.remove(self.cursor_line);
            self.cursor_line -= 1;
            self.cursor_column = self.current_line().chars().count();
            self.lines[self.cursor_line].push_str(&current);
            true
        } else {
            false
        }
    }

    pub fn delete(&mut self) -> bool {
        if self.cursor_column < self.current_line_length() {
            let byte = self.byte_index(self.cursor_line, self.cursor_column);
            self.lines[self.cursor_line].remove(byte);
            true
        } else if self.cursor_line + 1 < self.lines.len() {
            let next = self.lines.remove(self.cursor_line + 1);
            self.lines[self.cursor_line].push_str(&next);
            true
        } else {
            false
        }
    }

    pub fn move_left(&mut self) {
        if self.cursor_column > 0 {
            self.cursor_column -= 1;
        } else if self.cursor_line > 0 {
            self.cursor_line -= 1;
            self.cursor_column = self.current_line_length();
        }
    }

    pub fn move_right(&mut self) {
        if self.cursor_column < self.current_line_length() {
            self.cursor_column += 1;
        } else if self.cursor_line + 1 < self.lines.len() {
            self.cursor_line += 1;
            self.cursor_column = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cursor_line > 0 {
            self.cursor_line -= 1;
            self.cursor_column = self.cursor_column.min(self.current_line_length());
        }
    }

    pub fn move_down(&mut self) {
        if self.cursor_line + 1 < self.lines.len() {
            self.cursor_line += 1;
            self.cursor_column = self.cursor_column.min(self.current_line_length());
        }
    }

    pub fn move_home(&mut self) {
        self.cursor_column = 0;
    }

    pub fn move_end(&mut self) {
        self.cursor_column = self.current_line_length();
    }

    pub fn newline(&mut self) {
        let byte = self.byte_index(self.cursor_line, self.cursor_column);
        let remainder = self.lines[self.cursor_line].split_off(byte);
        self.lines.insert(self.cursor_line + 1, remainder);
        self.cursor_line += 1;
        self.cursor_column = 0;
    }

    pub fn delete_word(&mut self) -> bool {
        if self.cursor_column == 0 {
            // Matches the observed behaviour at the start of a line.
            return self.delete();
        }
        let line = self.current_line().to_string();
        let prefix: String = line.chars().take(self.cursor_column).collect();
        let separators = [' ', '-', '_', '/', ':', '\\'];
        let deletion_start = prefix
            .char_indices()
            .rev()
            .find(|(_, character)| separators.contains(character))
            .map(|(index, _)| prefix[..index].chars().count())
            .unwrap_or(0);
        if deletion_start >= self.cursor_column {
            return false;
        }
        let start_byte = self.byte_index(self.cursor_line, deletion_start);
        let end_byte = self.byte_index(self.cursor_line, self.cursor_column);
        self.lines[self.cursor_line].drain(start_byte..end_byte);
        self.cursor_column = deletion_start;
        true
    }

    pub fn cursor_display_width(&self) -> u16 {
        self.current_line()
            .chars()
            .take(self.cursor_column)
            .map(|character| UnicodeWidthChar::width(character).unwrap_or(0) as u16)
            .sum()
    }
}

#[derive(Clone)]
struct CacheState {
    raw_prefix: String,
    raw_offset: usize,
    prefix_lines: Vec<String>,
    output: String,
}

enum ExecKind {
    Normal,
    Cache(CacheState),
}

struct RunningProcess {
    kind: ExecKind,
    child: Child,
    stdout: Option<std::process::ChildStdout>,
    stderr: Option<std::process::ChildStderr>,
    started: Instant,
    command_raw: String,
}

struct CompletedProcess {
    status_success: bool,
    status_code: i32,
    stdout: String,
    stderr: String,
}

enum StartOutcome {
    Started,
    Immediate(Output),
    ImmediateCacheError(Output),
