pub struct App {
    pub config: PiprConfig,
    pub config_directory: PathBuf,
    history_path: PathBuf,
    bookmarks_path: PathBuf,
    pub history: Vec<String>,
    pub bookmarks: Vec<String>,
    pub input: TextField,
    pub mode: Mode,
    list: Option<OpenList>,
    chooser: Option<Chooser>,
    pub autoeval: bool,
    pub paranoid: bool,
    pub should_quit: bool,
    output: Output,
    executed_command: String,
    running: Option<RunningProcess>,
    running_is_cache: bool,
    cache: Option<CacheState>,
    history_position: Option<usize>,
    isolation: bool,
    spinner_index: usize,
    last_spinner_tick: Instant,
}

impl App {
    pub fn new(
        config: PiprConfig,
        config_directory: PathBuf,
        isolation: bool,
    ) -> App {
        let history_path = config_directory.join("history");
        let bookmarks_path = config_directory.join("bookmarks");
        let history_limit = config.history_size as usize;
        let history = commandlist::load_list(&history_path, Some(history_limit));
        let bookmarks = commandlist::load_list(&bookmarks_path, None);
        App {
            autoeval: config.autoeval_mode_default,
            paranoid: config.paranoid_history_mode_default,
            config,
            config_directory,
            history_path,
            bookmarks_path,
            history,
            bookmarks,
            input: TextField::default(),
            mode: Mode::Edit,
            list: None,
            chooser: None,
            should_quit: false,
            output: Output::Ok(String::new()),
            executed_command: String::new(),
            running: None,
            running_is_cache: false,
            cache: None,
            history_position: None,
            isolation,
            spinner_index: 0,
            last_spinner_tick: Instant::now(),
        }
    }

    pub fn current_command(&self) -> String {
        self.input.command_string()
    }

    fn history_size_limit(&self) -> usize {
        self.config.history_size as usize
    }

    fn save_history(&self) {
        commandlist::save_list_to_file(&self.history_path, &self.history);
    }

    fn save_bookmarks(&self) {
        commandlist::save_list_to_file(&self.bookmarks_path, &self.bookmarks);
    }

    fn push_history(&mut self, entry: &str) {
        if !entry.is_empty() && self.history.last().map(|last| last.as_str()) != Some(entry) {
            self.history.push(entry.to_string());
            let limit = self.history_size_limit();
            while self.history.len() > limit {
                self.history.remove(0);
            }
        }
        // The list is written even for a rejected duplicate, mirroring the
        // original save-on-push behaviour.
        self.save_history();
    }

    pub fn is_bookmarked(&self) -> bool {
        let current = self.current_command();
        self.bookmarks.iter().any(|entry| entry == &current)
    }

    fn toggle_bookmark(&mut self) {
        let current = self.current_command();
        if current.is_empty() {
            return;
        }
        if let Some(position) = self.bookmarks.iter().position(|entry| entry == &current) {
            self.bookmarks.remove(position);
        } else {
            self.bookmarks.push(current);
        }
        self.save_bookmarks();
    }

    pub fn executed_string_for(input: &str) -> String {
        input
            .split('\n')
            .filter(|line| !line.starts_with('#'))
            .collect::<Vec<_>>()
            .join(" ")
    }

    fn full_execution_string(&self) -> String {
        let command = self.current_command();
        Self::executed_string_for(&command)
    }

    fn build_shell_command(&self, command_to_execute: &str) -> Vec<String> {
        let mut shell_command: Vec<String> = Vec::new();
        if self.isolation {
            shell_command.extend(
                [
                    "bwrap",
                    "--ro-bind",
                    "/",
                    "/",
                    "--tmpfs",
                    "/tmp",
                    "--dev",
                    "/dev",
                    "--proc",
                    "/proc",
                    "--die-with-parent",
                    "--share-net",
                    "--unshare-pid",
                ]
                .iter()
                .map(|part| part.to_string()),
            );
        }
        shell_command.extend(self.config.eval_environment.iter().cloned());
        shell_command.push(command_to_execute.to_string());
        shell_command
    }

    fn start_process(
        &mut self,
        execution_string: &str,
        stdin_data: Option<String>,
        kind: ExecKind,
        command_raw: String,
    ) -> StartOutcome {
        self.kill_running();
        let is_cache = matches!(kind, ExecKind::Cache(_));
        let shell_command = self.build_shell_command(execution_string);
        if shell_command.is_empty() {
            let output = Output::Err("shell_command is empty".to_string());
            if is_cache {
                return StartOutcome::ImmediateCacheError(output);
            }
            return StartOutcome::Immediate(output);
        }
        let program = shell_command[0].clone();
        let arguments = &shell_command[1..];
        let stdin_mode = if stdin_data.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        };
        let mut command = Command::new(&program);
        command
            .args(arguments)
            .stdin(stdin_mode)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(_) => {
                let output = Output::Err("Unable to spawn command".to_string());
                if is_cache {
                    return StartOutcome::ImmediateCacheError(output);
                }
                return StartOutcome::Immediate(output);
            }
        };
        if let Some(data) = stdin_data {
            if let Some(mut stdin) = child.stdin.take() {
                std::thread::spawn(move || {
                    let _ = stdin.write_all(data.as_bytes());
                });
            }
        }
        let stdout = child.stdout.take();
        let stderr = child.stderr.take();
        self.running = Some(RunningProcess {
            kind,
            child,
            stdout,
            stderr,
            started: Instant::now(),
            command_raw,
        });
        self.running_is_cache = is_cache;
        StartOutcome::Started
    }

    fn kill_running(&mut self) {
        if let Some(mut running) = self.running.take() {
            let _ = running.child.kill();
            let _ = running.child.wait();
        }
        self.running_is_cache = false;
    }

    pub fn kill_running_on_exit(&mut self) {
        self.kill_running();
    }

    fn bytes_to_string(bytes: Vec<u8>) -> String {
        match String::from_utf8(bytes) {
            Ok(text) => text,
            Err(_) => "stream did not contain valid UTF-8".to_string(),
        }
    }

    pub fn poll_running(&mut self) {
        let timeout = Duration::from_millis(self.config.cmd_timeout_millis as u64);
        let completed: Option<(ExecKind, String, Result<CompletedProcess, Output>)>;
        if let Some(running) = self.running.as_mut() {
            let elapsed = running.started.elapsed();
            match running.child.try_wait() {
                Ok(Some(status)) => {
                    let mut stdout_bytes = Vec::new();
                    if let Some(mut stdout) = running.stdout.take() {
                        let _ = stdout.read_to_end(&mut stdout_bytes);
                    }
                    let mut stderr_bytes = Vec::new();
                    if let Some(mut stderr) = running.stderr.take() {
                        let _ = stderr.read_to_end(&mut stderr_bytes);
                    }
                    let process = CompletedProcess {
                        status_success: status.success(),
                        status_code: status.code().unwrap_or(-1),
                        stdout: Self::bytes_to_string(stdout_bytes),
                        stderr: Self::bytes_to_string(stderr_bytes),
                    };
                    completed = Some((
                        // Placeholder, kind is moved below.
                        ExecKind::Normal,
                        String::new(),
                        Ok(process),
                    ));
                    // The placeholder is replaced by the real completion in
                    // the block after this match; this variable is not used
                    // in that form.
                    let _ = completed;
                    let mut taken = self.running.take().expect("running process");
                    self.running_is_cache = false;
                    let command_raw = std::mem::take(&mut taken.command_raw);
                    let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                    self.complete_execution(kind, command_raw, Ok(process));
                    return;
                }
                Ok(None) => {
                    if elapsed >= timeout {
                        let mut taken = self.running.take().expect("running process");
                        self.running_is_cache = false;
                        let _ = taken.child.kill();
                        let _ = taken.child.wait();
                        let command_raw = std::mem::take(&mut taken.command_raw);
                        let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                        self.complete_execution(
                            kind,
                            command_raw,
                            Err(Output::Err("Command timed out".to_string())),
                        );
                        return;
                    }
                }
                Err(_) => {
                    let mut taken = self.running.take().expect("running process");
                    self.running_is_cache = false;
                    let command_raw = std::mem::take(&mut taken.command_raw);
                    let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                    self.complete_execution(
                        kind,
                        command_raw,
                        Err(Output::Err("Unable to spawn command".to_string())),
                    );
                    return;
                }
            }
        }
    }

    fn complete_execution(
        &mut self,
        kind: ExecKind,
        command_raw: String,
        result: Result<CompletedProcess, Output>,
    ) {
        match kind {
            ExecKind::Normal => {
                let output = match result {
                    Ok(process) => {
                        if process.status_success {
                            Output::Ok(process.stdout)
                        } else {
                            Output::Err(process.stderr)
                        }
                    }
                    Err(output) => output,
                };
                let succeeded = matches!(output, Output::Ok(_));
                self.output = output;
                if succeeded && self.paranoid && self.autoeval {
                    self.push_history(&command_raw);
                }
            }
            ExecKind::Cache(cache_candidate) => match result {
                Ok(process) => {
                    if process.status_success {
                        let candidate = CacheState {
                            output: process.stdout,
                            ..cache_candidate
                        };
                        if self.cache_prefix_still_matches(&candidate) {
                            self.cache = Some(candidate);
                        }
                    } else {
                        self.output = Output::Err(format!(
                            "could not run command to cache: Non-zero exit code: {}",
                            process.status_code
                        ));
                        self.executed_command = self.current_command();
                    }
                }
                Err(output) => {
                    self.output = output;
                    self.executed_command = self.current_command();
                }
            },
        }
    }

    fn cache_prefix_still_matches(&self, cache: &CacheState) -> bool {
        let current = self.current_command();
        let characters: Vec<char> = current.chars().collect();
        if characters.len() <= cache.raw_offset {
            return false;
        }
        let prefix: String = characters.iter().take(cache.raw_offset).collect();
        prefix == cache.raw_prefix && characters.get(cache.raw_offset) == Some(&'|')
    }

    fn validate_cache_after_edit(&mut self) {
        let keep = match &self.cache {
            Some(cache) => self.cache_prefix_still_matches(cache),
            None => false,
        };
        if !keep {
            self.cache = None;
        }
    }

    pub fn start_evaluation(&mut self) {
        let raw_command = self.current_command();
        let (execution_string, stdin_data) = if let Some(cache) = self.cache.clone() {
            if self.cache_prefix_still_matches(&cache) {
                (self.suffix_execution_string(&cache), Some(cache.output.clone()))
            } else {
                self.cache = None;
                (self.full_execution_string(), None)
            }
        } else {
            (self.full_execution_string(), None)
        };
        self.executed_command = raw_command.clone();
        match self.start_process(&execution_string, stdin_data, ExecKind::Normal, raw_command) {
            StartOutcome::Started => {}
            StartOutcome::Immediate(output) => {
                self.output = output;
            }
            StartOutcome::ImmediateCacheError(output) => {
                self.output = output;
            }
        }
    }

    fn suffix_execution_string(&self, cache: &CacheState) -> String {
        let mut suffix_lines: Vec<String> = Vec::new();
        if self.input.cursor_line < self.input.lines.len() {
            // The suffix is independent from the cursor at evaluation time:
            // it is built from the stored pipe position in the stored
            // prefix lines. The last stored prefix line is partial.
        }
        let _ = &cache.prefix_lines;
        // Rebuild from the raw command using raw_offset.
        let current = self.current_command();
        let suffix_raw: String = current
            .chars()
            .skip(cache.raw_offset + 1)
            .collect::<String>();
        for line in suffix_raw.split('\n') {
            suffix_lines.push(line.to_string());
        }
        suffix_lines
            .iter()
            .filter(|line| !line.starts_with('#'))
            .cloned()
            .collect::<Vec<_>>()
            .join(" ")
    }

    fn start_autoeval_if_needed(&mut self, changed: bool) {
        if changed && self.autoeval {
            self.start_evaluation();
        }
    }
