    fn word_under_cursor(&self) -> String {
        let line = self.input.current_line();
        let mut traversed = 0usize;
        for part in line.split(' ') {
            traversed += part.chars().count() + 1;
            if traversed > self.input.cursor_column {
                return part.to_string();
            }
        }
        String::new()
