    fn open_chooser(&mut self, kind: ChooserKind) {
        let mut items: Vec<(String, String, String)> = Vec::new();
        match kind {
            ChooserKind::Snippets => {
                for (key, value) in &self.config.snippets {
                    items.push((
                        key.clone(),
                        format!("{}: {}", key, value.replace("||", "")),
                        value.clone(),
                    ));
                }
            }
            ChooserKind::HelpViewers => {
                let word = self.word_under_cursor();
                if word.is_empty() {
                    return;
                }
                for (key, value) in &self.config.help_viewers {
                    let expanded = value.replace("??", &word);
                    items.push((key.clone(), format!("{}: {}", key, expanded), expanded));
                }
            }
            ChooserKind::OutputViewers => {
                for (key, value) in &self.config.output_viewers {
                    items.push((key.clone(), format!("{}: {}", key, value), value.clone()));
                }
            }
        }
        self.chooser = Some(Chooser { kind, items });
    }

    fn open_list(&mut self, kind: ListKind) {
        // Toggle off when the same list is already visible.
        if let Some(open) = &self.list {
            if open.kind == kind {
                self.list = None;
                if self.mode == Mode::HistoryList || self.mode == Mode::BookmarksList {
                    self.mode = Mode::Edit;
                }
                return;
            }
        }
        self.chooser = None;
        self.history_position = None;
        let current = self.current_command();
        self.push_history(&current);
        let (entries, mode) = match kind {
            ListKind::History => (self.history.clone(), Mode::HistoryList),
            ListKind::Bookmarks => (self.bookmarks.clone(), Mode::BookmarksList),
        };
        let mut state = ListState::default();
        if entries.is_empty() {
            state.select(None);
        } else {
            state.select(Some(entries.len() - 1));
        }
        self.list = Some(OpenList {
            kind,
            entries,
            state,
        });
        self.mode = mode;
    }

    fn close_list(&mut self, use_selection: bool) {
        let Some(mut open) = self.list.take() else {
            self.mode = Mode::Edit;
            return;
        };
        let selected_index = open.selected_index();
        let selected = open.selected_entry().map(|entry| entry.to_string());
        match open.kind {
            ListKind::History => {
                self.history = std::mem::take(&mut open.entries);
                self.save_history();
            }
            ListKind::Bookmarks => {
                self.bookmarks = std::mem::take(&mut open.entries);
                self.save_bookmarks();
            }
        }
        self.mode = Mode::Edit;
        if use_selection {
            if let Some(entry) = selected {
                self.input.set_command(&entry);
                self.cache = None;
                if open.kind == ListKind::History {
                    self.history_position = selected_index;
                } else {
                    self.history_position = None;
                }
            }
        }
    }

    fn history_previous(&mut self) {
        if self.history.is_empty() {
            return;
        }
        if self.history_position.is_none() {
            let mut position = self.history.len();
            let current = self.current_command();
            self.push_history(&current);
            position = position.saturating_sub(1);
            self.history_position = Some(position);
        } else if let Some(position) = self.history_position {
            if position > 0 {
                self.history_position = Some(position - 1);
            }
        }
        if let Some(position) = self.history_position {
            if let Some(entry) = self.history.get(position).cloned() {
                self.input.set_command(&entry);
                self.cache = None;
                // set_command does not alter navigation position.
                self.history_position = Some(position);
            }
        }
    }

    fn history_next(&mut self) {
        if self.history.is_empty() {
            return;
        }
        if let Some(position) = self.history_position {
            let next = position + 1;
            if next >= self.history.len().saturating_sub(1) {
                self.history_position = None;
                self.input.set_command("");
                self.cache = None;
                self.history_position = None;
            } else {
                self.history_position = Some(next);
                if let Some(entry) = self.history.get(next).cloned() {
                    self.input.set_command(&entry);
                    self.cache = None;
                    self.history_position = Some(next);
                }
            }
        }
    }

    fn quit(&mut self) {
        let current = self.current_command();
        self.push_history(&current);
        self.should_quit = true;
    }

    fn cache_at_cursor(&mut self) {
        let line_index = self.input.cursor_line;
        let column = self.input.cursor_column;
        let line = self.input.current_line().to_string();
        if line.chars().nth(column) != Some('|') {
            return;
        }
        let mut raw_prefix_lines: Vec<String> = Vec::new();
        for entry in self.input.lines.iter().take(line_index) {
            raw_prefix_lines.push(entry.clone());
        }
        let prefix_part: String = line.chars().take(column).collect();
        raw_prefix_lines.push(prefix_part);
        let raw_prefix = raw_prefix_lines.join("\n");
        let raw_offset = raw_prefix.chars().count();
        let prefix_execution = raw_prefix_lines
            .iter()
            .filter(|entry| !entry.starts_with('#'))
            .cloned()
            .collect::<Vec<_>>()
            .join(" ");
        let candidate = CacheState {
            raw_prefix: raw_prefix.clone(),
            raw_offset,
            prefix_lines: raw_prefix_lines,
            output: String::new(),
        };
        let raw_command = self.current_command();
        match self.start_process(
            &prefix_execution,
            None,
            ExecKind::Cache(candidate),
            raw_command,
        ) {
            StartOutcome::Started => {}
            StartOutcome::Immediate(output) => {
                self.output = output;
                self.executed_command = self.current_command();
            }
            StartOutcome::ImmediateCacheError(output) => {
                self.output = output;
                self.executed_command = self.current_command();
            }
        }
    }

    fn choose_item(&mut self, key: &str) {
        let Some(chooser) = self.chooser.take() else {
            return;
        };
        let selected = chooser
            .items
            .iter()
            .find(|(item_key, _, _)| item_key == key)
            .map(|(_, _, action)| (chooser.kind, action.clone()));
        if let Some((kind, action)) = selected {
            match kind {
                ChooserKind::Snippets => {
                    let placeholder = action.find("||").map(|index| index);
                    let cleaned = action.replace("||", "");
                    let offset = placeholder.unwrap_or(cleaned.chars().count());
                    self.input.insert_snippet_text(&cleaned, offset);
                    self.history_position = None;
                    self.validate_cache_after_edit();
                }
                ChooserKind::HelpViewers => {
                    self.run_help_viewer(&action);
                }
                ChooserKind::OutputViewers => {
                    let feed = self.output.stdout_text().to_string();
                    self.run_output_viewer(&action, &feed);
                }
            }
        }
    }

    fn run_help_viewer(&mut self, command: &str) {
        let _ = run_external(|| {
            let status = Command::new("bash")
                .arg("-c")
                .arg(command)
                .spawn()
                .and_then(|mut child| child.wait())?;
            Ok(status)
        });
    }

    fn run_output_viewer(&mut self, viewer: &str, output: &str) {
        let output_owned = output.to_string();
        let viewer_owned = viewer.to_string();
        let _ = run_external(move || {
            let mut child = Command::new(&viewer_owned)
                .stdin(Stdio::piped())
                .spawn()?;
            if let Some(mut stdin) = child.stdin.take() {
                if output_owned.ends_with('\n') || output_owned.is_empty() {
                    if output_owned.is_empty() {
                        stdin.write_all(b"\n")?;
                    } else {
                        stdin.write_all(output_owned.as_bytes())?;
                    }
                } else {
                    stdin.write_all(output_owned.as_bytes())?;
                    stdin.write_all(b"\n")?;
                }
            }
            child.wait()
        });
    }

    pub fn tick_spinner(&mut self) {
        if self.last_spinner_tick.elapsed() >= Duration::from_millis(100) {
            self.spinner_index = (self.spinner_index + 1) % SPINNER_FRAMES.len();
            self.last_spinner_tick = Instant::now();
        }
    }

    pub fn handle_key(&mut self, key: KeyEvent) {
        // Global mode-independent toggles.
        if key.code == KeyCode::F(1) {
            self.chooser = None;
            if self.mode == Mode::Help {
                self.mode = Mode::Edit;
            } else {
                self.mode = Mode::Help;
                self.list = None;
            }
            return;
        }
        if key.code == KeyCode::F(4) {
            self.open_list(ListKind::History);
            return;
        }
        if key.code == KeyCode::Char('b')
            && key.modifiers.contains(KeyModifiers::CONTROL)
        {
            self.open_list(ListKind::Bookmarks);
            return;
        }

        if self.mode == Mode::Help {
            self.mode = Mode::Edit;
            return;
        }

        if self.chooser.is_some() {
            if let KeyCode::Char(character) = key.code {
                self.choose_item(&character.to_string());
            } else {
                self.chooser = None;
            }
            return;
        }

        if self.mode == Mode::HistoryList || self.mode == Mode::BookmarksList {
            self.handle_list_key(key);
            return;
        }

        self.handle_edit_key(key);
    }

    fn handle_list_key(&mut self, key: KeyEvent) {
        let Some(list) = self.list.as_mut() else {
            self.mode = Mode::Edit;
            return;
        };
        match key.code {
            KeyCode::Up => {
                if let Some(selected) = list.state.selected() {
                    list.state.select(Some(selected.saturating_sub(1)));
                }
            }
            KeyCode::Down => {
                if let Some(selected) = list.state.selected() {
                    if !list.entries.is_empty() {
                        list.state
                            .select(Some((selected + 1).min(list.entries.len() - 1)));
                    }
                }
            }
            KeyCode::PageUp => {
                if !list.entries.is_empty() {
                    list.state.select(Some(0));
                }
            }
            KeyCode::PageDown => {
                if !list.entries.is_empty() {
                    list.state.select(Some(list.entries.len() - 1));
                }
            }
            KeyCode::Delete | KeyCode::Backspace => {
                if let Some(selected) = list.state.selected() {
                    if selected < list.entries.len() {
                        list.entries.remove(selected);
                        if list.entries.is_empty() {
                            list.state.select(None);
                        } else if selected >= list.entries.len() {
                            list.state.select(Some(list.entries.len() - 1));
                        } else {
                            list.state.select(Some(selected));
                        }
                    }
                }
            }
            KeyCode::Enter => {
                self.close_list(true);
            }
            KeyCode::Esc => {
                self.close_list(false);
            }
            _ => {}
        }
    }

    fn handle_edit_key(&mut self, key: KeyEvent) {
        let control = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => {
                self.quit();
            }
            KeyCode::Char('c') if control => {
                self.quit();
            }
            KeyCode::Char('q') if control => {
                self.quit();
            }
            KeyCode::Enter => {
                if key.modifiers.contains(KeyModifiers::ALT) {
                    self.input.newline();
                    self.history_position = None;
                    self.validate_cache_after_edit();
                    self.start_autoeval_if_needed(true);
                } else {
                    let current = self.current_command();
                    self.push_history(&current);
                    self.start_evaluation();
                }
            }
            KeyCode::Insert => {
                self.input.newline();
                self.history_position = None;
                self.validate_cache_after_edit();
                self.start_autoeval_if_needed(true);
            }
            KeyCode::F(2) => {
                self.autoeval = !self.autoeval;
            }
            KeyCode::F(3) => {
                self.paranoid = !self.paranoid;
            }
            KeyCode::F(5) => {
                self.open_chooser(ChooserKind::HelpViewers);
            }
            KeyCode::F(6) => {
                self.open_chooser(ChooserKind::OutputViewers);
            }
            KeyCode::F(7) => {
                self.cache_at_cursor();
            }
            KeyCode::Char('s') if control => {
                self.toggle_bookmark();
            }
            KeyCode::Char('v') if control => {
                self.open_chooser(ChooserKind::Snippets);
            }
            KeyCode::Char('p') if control => {
                self.history_previous();
            }
            KeyCode::Char('n') if control => {
                self.history_next();
            }
            KeyCode::Char('u') if control => {
                self.input.clear();
                self.history_position = None;
                self.validate_cache_after_edit();
                self.start_autoeval_if_needed(true);
            }
            KeyCode::Char('w') if control => {
                let changed = self.input.delete_word();
                if changed {
                    self.history_position = None;
                }
                self.validate_cache_after_edit();
                self.start_autoeval_if_needed(changed);
            }
            KeyCode::Char('a') if control => {
                self.input.move_home();
