                self.history_position = None;
            }
            KeyCode::Char(character) => {
                self.input.insert_char(character);
                self.history_position = None;
                self.validate_cache_after_edit();
                self.start_autoeval_if_needed(true);
            }
            KeyCode::Backspace => {
                let changed = self.input.backspace();
                if changed {
                    self.history_position = None;
                }
                self.validate_cache_after_edit();
                self.start_autoeval_if_needed(changed);
            }
            KeyCode::Delete => {
                let changed = self.input.delete();
                if changed {
