fn primary_title_style() -> Style {
    Style::default().fg(Color::Black).bg(Color::Cyan)
}

fn secondary_title_style() -> Style {
    Style::default().fg(Color::Cyan)
}

fn titled_block(title: String, primary: bool) -> Block<'static> {
    let style = if primary {
        primary_title_style()
    } else {
        secondary_title_style()
    };
    Block::default()
        .borders(Borders::ALL)
        .title(Span::styled(title, style))
