    }
}

fn truncate_input_lines(
    lines: Vec<Line<'static>>,
    plain_lines: &[String],
    width: u16,
) -> Vec<Line<'static>> {
    let mut result = Vec::new();
    for (line, plain) in lines.into_iter().zip(plain_lines.iter()) {
        let plain_width: usize = plain
            .chars()
            .map(|character| UnicodeWidthChar::width(character).unwrap_or(0))
            .sum();
        if width == 0 {
            result.push(Line::from(""));
            continue;
        }
        if plain_width <= width as usize {
            result.push(line);
            continue;
        }
        let target = width.saturating_sub(3) as usize;
        let mut collected: Vec<Span> = Vec::new();
        let mut remaining = target;
        for span in line.spans {
            if remaining == 0 {
                break;
            }
            let mut text = String::new();
            for character in span.content.chars() {
                let char_width = UnicodeWidthChar::width(character).unwrap_or(0);
                if char_width > remaining {
                    break;
                }
                remaining -= char_width;
                text.push(character);
            }
            if !text.is_empty() {
                collected.push(Span::styled(text, span.style));
            }
            if remaining == 0 {
                break;
            }
        }
        collected.push(Span::raw("..."));
        result.push(Line::from(collected));
    }
    result
}

pub fn is_bwrap_available() -> bool {
    let Some(path_value) = std::env::var_os("PATH") else {
        return false;
    };
    for directory in std::env::split_paths(&path_value) {
        let candidate = if directory.as_os_str().is_empty() {
            PathBuf::from("bwrap")
        } else {
            directory.join("bwrap")
        };
        if candidate.is_file() {
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                if let Ok(metadata) = candidate.metadata() {
                    if metadata.permissions().mode() & 0o111 != 0 {
                        return true;
                    } else {
                        continue;
                    }
                }
            }
            return true;
        }
    }
    false
}

