#[derive(Clone, Copy, PartialEq, Eq)]
enum OptionKind {
    Argument,
    Flag,
}

struct OptionSpec {
    short: Option<char>,
    long: Option<&'static str>,
    kind: OptionKind,
}

impl OptionSpec {
    fn canonical(&self) -> String {
        if let Some(long) = self.long {
            long.to_string()
        } else if let Some(short) = self.short {
            short.to_string()
        } else {
            String::new()
        }
    }
}

const OPTION_SPECS: &[OptionSpec] = &[
    OptionSpec { short: Some('d'), long: Some("default"), kind: OptionKind::Argument },
    OptionSpec { short: Some('o'), long: Some("out-file"), kind: OptionKind::Argument },
    OptionSpec { short: None, long: Some("in-file"), kind: OptionKind::Argument },
    OptionSpec { short: None, long: Some("config-reference"), kind: OptionKind::Flag },
    OptionSpec { short: Some('r'), long: Some("raw-mode"), kind: OptionKind::Flag },
    OptionSpec { short: None, long: Some("no-isolation"), kind: OptionKind::Flag },
    OptionSpec { short: Some('h'), long: Some("help"), kind: OptionKind::Flag },
];

fn config_directory() -> PathBuf {
    let home_directory = std::env::var("HOME").expect("$HOME not set");
    match std::env::var("XDG_CONFIG_HOME") {
        Ok(directory) if !directory.is_empty() => PathBuf::from(directory).join("pipr"),
        _ => PathBuf::from(home_directory).join(".config").join("pipr"),
    }
}

#[derive(Default)]
struct ParsedArgs {
    present: Vec<String>,
    values: std::collections::HashMap<String, String>,
}

impl ParsedArgs {
    fn has(&self, name: &str) -> bool {
        self.present.iter().any(|item| item == name)
    }
    fn value(&self, name: &str) -> Option<&str> {
        self.values.get(name).map(|value| value.as_str())
    }
}

fn find_long(name: &str) -> Option<&'static OptionSpec> {
    OPTION_SPECS.iter().find(|spec| spec.long == Some(name))
}

fn find_short(character: char) -> Option<&'static OptionSpec> {
    OPTION_SPECS.iter().find(|spec| spec.short == Some(character))
}

fn parse_args(arguments: &[String]) -> Result<ParsedArgs, String> {
    let mut parsed = ParsedArgs::default();
    let mut free_ended = false;
    let mut index = 1usize;
    while index < arguments.len() {
        let argument = &arguments[index];
        if free_ended
            || argument == "-"
            || argument.is_empty()
            || !argument.starts_with('-')
        {
            index += 1;
            continue;
        }
        if argument == "--" {
            free_ended = true;
            index += 1;
            continue;
        }
        if let Some(long_text) = argument.strip_prefix("--") {
            let (name, inline_value) = match long_text.find('=') {
                Some(position) => (
                    &long_text[..position],
                    Some(long_text[position + 1..].to_string()),
                ),
                None => (long_text, None),
            };
            let spec = if let Some(spec) = find_long(name) {
                spec
            } else if name.chars().count() == 1 {
                let character = name.chars().next().unwrap();
                match find_short(character) {
                    Some(spec) => spec,
                    None => return Err(format!("Unrecognized option: '{}'", name)),
                }
            } else {
                return Err(format!("Unrecognized option: '{}'", name));
            };
            let canonical = spec.canonical();
            match spec.kind {
                OptionKind::Flag => {
                    if inline_value.is_some() {
                        return Err(format!(
                            "Option '{}' does not take an argument",
                            name
                        ));
                    }
                    if parsed.has(&canonical) {
                        return Err(format!("Option '{}' given more than once", canonical));
                    }
                    parsed.present.push(canonical);
                }
                OptionKind::Argument => {
                    let value = if let Some(value) = inline_value {
                        value
                    } else if index + 1 < arguments.len() {
                        index += 1;
                        arguments[index].clone()
                    } else {
                        return Err(format!("Argument to option '{}' missing", name));
                    };
                    if parsed.has(&canonical) {
                        return Err(format!("Option '{}' given more than once", canonical));
                    }
                    parsed.present.push(canonical.clone());
                    parsed.values.insert(canonical, value);
                }
            }
            index += 1;
            continue;
        }
        // Short option cluster.
        let cluster: Vec<char> = argument[1..].chars().collect();
        let mut cluster_index = 0usize;
        while cluster_index < cluster.len() {
            let character = cluster[cluster_index];
            let Some(spec) = find_short(character) else {
                return Err(format!("Unrecognized option: '{}'", character));
            };
            let canonical = spec.canonical();
            match spec.kind {
                OptionKind::Flag => {
                    if parsed.has(&canonical) {
                        return Err(format!("Option '{}' given more than once", canonical));
                    }
                    parsed.present.push(canonical);
                    cluster_index += 1;
                }
                OptionKind::Argument => {
                    let value = if cluster_index + 1 < cluster.len() {
                        cluster[cluster_index + 1..].iter().collect::<String>()
                    } else if index + 1 < arguments.len() {
                        index += 1;
                        arguments[index].clone()
                    } else {
                        return Err(format!("Argument to option '{}' missing", character));
                    };
                    if parsed.has(&canonical) {
                        return Err(format!("Option '{}' given more than once", canonical));
                    }
                    parsed.present.push(canonical.clone());
                    parsed.values.insert(canonical, value);
                    break;
                }
            }
        }
        index += 1;
    }
    Ok(parsed)
}

