                    if app.should_quit {
                        break;
                    }
                    if !crossterm::event::poll(std::time::Duration::from_millis(0))? {
                        break;
                    }
                }
                // After a burst of input, (re)start evaluation once if the
                // last edits requested it. The individual key handlers have
                // already done this for single keys; repeated calls are
                // avoided by not tracking a separate pending flag.
            }
        }
        Ok(())
    })();
    app.kill_running_on_exit();
    guard.restore();
    result
}

fn real_main() -> io::Result<i32> {
    let arguments: Vec<String> = std::env::args().collect();
    let program = arguments.first().cloned().unwrap_or_default();
    let parsed = match parse_args(&arguments) {
        Ok(parsed) => parsed,
        Err(error) => {
            eprintln!("{}: {}", program, error);
            return Ok(1);
        }
    };
    if parsed.has("help") {
        println!("{}", usage(&program));
        return Ok(0);
    }
    if parsed.has("config-reference") {
        println!("{}", pipr_config::DEFAULT_CONFIG);
        return Ok(0);
    }

    let config_dir = config_directory();
    let config = PiprConfig::new(&config_dir);
    let isolation = !parsed.has("no-isolation");
    if isolation && !app::is_bwrap_available() {
        println!(
            "bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode"
        );
        io::stdout().flush()?;
        return Ok(1);
    }

    let mut application = App::new(config.clone(), config_dir, isolation);

    let initial_command = if let Some(in_file) = parsed.value("in-file") {
        Some(std::fs::read_to_string(in_file)?)
    } else if let Some(default) = parsed.value("default") {
        Some(default.to_string())
    } else {
        None
    };
    if let Some(initial) = initial_command {
        application.input.set_command(&initial);
    }

    run_application(&mut application)?;

    let raw_mode = parsed.has("raw-mode");
    let current = application.current_command();
    let finished = if raw_mode {
        current.clone()
    } else {
        current.replace('\n', " ")
    };

    if let Some(hook) = config.finish_hook.clone() {
        run_finish_hook(&hook, &finished)?;
    }
    println!("{}", finished);
    if let Some(out_file) = parsed.value("out-file") {
        std::fs::write(out_file, &finished)?;
    }
    Ok(0)
}

fn run_finish_hook(hook: &str, finished_command: &str) -> io::Result<()> {
    let mut pieces = hook.split(' ');
    let program = pieces.next().unwrap_or("");
    let arguments: Vec<&str> = pieces.collect();
    let mut child = std::process::Command::new(program)
        .args(&arguments)
        .stdin(std::process::Stdio::piped())
        .spawn()?;
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(finished_command.as_bytes())?;
    }
    let _ = child.wait()?;
    Ok(())
}

fn main() -> ExitCode {
    match real_main() {
        Ok(code) => ExitCode::from(code as u8),
        Err(error) => {
            eprintln!("Error: {}", error);
            ExitCode::from(1)
        }
    }
}
RS
