import subprocess, time, os, shutil

def run_binary(binary, label, config=None, history=None, bookmarks=None, actions=None, args="--no-isolation", w=80, h=24):
    home=f"/tmp/diff_{label}"
    shutil.rmtree(home, ignore_errors=True); os.makedirs(home+"/.config/pipr", exist_ok=True)
    if config is not None: open(home+"/.config/pipr/pipr.toml","w").write(config)
    if history is not None: open(home+"/.config/pipr/history","w").write(history)
    if bookmarks is not None: open(home+"/.config/pipr/bookmarks","w").write(bookmarks)
    session=f"d{label}"
    subprocess.run(["tmux","kill-session","-t",session], stderr=subprocess.DEVNULL)
    stdout_file=f"/tmp/diff_stdout_{label}.txt"
    if os.path.exists(stdout_file): os.remove(stdout_file)
    # Wrap to redirect stdout to file while stdin/stderr stay tty? That changes stderr UI behaviour? For most tests keep combined pane (no redirect).
    cmd=f"HOME={home} {binary} {args}; echo EXIT:$?; sleep 100"
    subprocess.run(["tmux","new-session","-d","-s",session,"-x",str(w),"-y",str(h), cmd])
    time.sleep(0.6)
    def cap(esc=False):
        a=["tmux","capture-pane","-t",session,"-p","-J"]
        if esc: a.append("-e")
        return subprocess.run(a,capture_output=True,text=True).stdout
    def send(*keys, delay=0.35):
        subprocess.run(["tmux","send-keys","-t",session,*keys]); time.sleep(delay)
    def text(txt, delay=0.35):
        subprocess.run(["tmux","send-keys","-t",session,"-l",txt]); time.sleep(delay)
    snaps=[]
    snaps.append(("initial", cap(), cap(True)))
    for action in (actions or []):
        if isinstance(action, tuple) and action[0]=="text": text(action[1])
        elif isinstance(action, tuple) and action[0]=="sleep": time.sleep(action[1])
        elif isinstance(action, tuple) and action[0]=="snap": pass
        else: send(action)
        snaps.append((str(action), cap(), cap(True)))
    files={}
    for root, dirs, fs in os.walk(home):
        for fn in fs:
            path=os.path.join(root,fn)
            rel=os.path.relpath(path,home)
            if rel.endswith("pipr.toml"): continue
            files[rel]=open(path,"rb").read()
    subprocess.run(["tmux","kill-session","-t",session], stderr=subprocess.DEVNULL)
    return {"snaps":snaps,"files":files}

def compare(name, **kwargs):
    esc_compare=kwargs.pop("esc_compare", False)
    orig=run_binary("/tmp/original_executable","orig_"+name, **kwargs)
    ours=run_binary("/workspace/executable","ours_"+name, **kwargs)
    ok=True
    if len(orig["snaps"]) != len(ours["snaps"]):
        print(name,"snap count mismatch"); return False
    for (o_label,o_plain,o_esc),(u_label,u_plain,u_esc) in zip(orig["snaps"],ours["snaps"]):
        compare_plain = o_plain==u_plain
        compare_esc = (o_esc==u_esc)
        if not compare_plain or (esc_compare and not compare_esc):
            ok=False
            print(f"\n=== DIFF {name} after {o_label} plain_ok={compare_plain} esc_ok={compare_esc} ===")
            import difflib
            if not compare_plain:
                print("\n".join(difflib.unified_diff(o_plain.splitlines(),u_plain.splitlines(),fromfile="orig",tofile="ours",lineterm="")))
            if esc_compare and not compare_esc:
                print("ESC ORIG:",repr(o_esc))
                print("ESC OURS:",repr(u_esc))
    if orig["files"]!=ours["files"]:
        ok=False
        print(f"\n=== FILES DIFF {name} orig={orig['files']} ours={ours['files']} ===")
    if ok: print(f"OK {name}")
    return ok
