        //    it, the history and bookmark files) is created if it does not
        //    exist yet.
        // 2. If there is no configuration file yet, the reference
        //    configuration is written out. A user can edit that file in
        //    place; it is never overwritten once it exists.
        // 3. The file is then read and parsed. Individual values are
        //    deliberately looked up in a forgiving way below: a value with
        //    an unexpected type falls back to the documented default for
        //    that one setting instead of making the whole file unusable,
        //    while a syntactically invalid file is a hard error.
        //
        // Most settings use the defaults that are also documented in the
        // reference configuration. The exceptions are intentional: when a
        // toggle is absent it is off, except for highlighting, which is
        // on unless it is explicitly disabled.
        //
        //
        //
        //
        std::fs::create_dir_all(&pipr_configuration_directory.as_path()).unwrap();
        if !config_file_path.exists() {
            write_default_config_file(&config_file_path);
        }

        let loaded_value = load_config_value(
            &config_file_path,
        )
            .unwrap();''')
p.write_text(s)
