import pathlib
p=pathlib.Path("src/pipr_config.rs"); s=p.read_text()
old='''    let value: Value = toml::from_str(&contents).map_err(|error| {
        ConfigError(format!(
            "{}\\n in {}",
            error.to_string().trim_end(),
            relative_display_path(path)
        ))
