# add translator before load_config_value
translator=r'''
fn translate_parse_error(contents: &str, rendered: &str) -> String {
    let rendered_lines: Vec<&str> = rendered.lines().collect();
    if rendered_lines.len() < 5 {
        return rendered.trim_end().to_string();
    }
    let header = rendered_lines[0];
    let Some(line_marker) = header.find("line ") else {
        return rendered.trim_end().to_string();
    };
    let after_line = &header[line_marker + 5..];
    let Some(comma) = after_line.find(',') else {
        return rendered.trim_end().to_string();
    };
    let line_number: usize = after_line[..comma].trim().parse().unwrap_or(1);
    let column_marker = after_line.find("column ").map(|index| index + 7).unwrap_or(1);
    let mut column: usize = after_line[column_marker..]
        .trim()
        .parse()
        .unwrap_or(1);
    let message = rendered_lines[rendered_lines.len() - 1].trim();
    let source_line = contents
        .lines()
        .nth(line_number.saturating_sub(1))
