                        let width = inner.width as usize;
                        let text_width: usize = text
                            .chars()
                            .map(|character| {
                                UnicodeWidthChar::width(character).unwrap_or(0)
                            })
                            .sum();
                        let mut padded = text;
                        if text_width < width {
                            padded.push_str(&" ".repeat(width - text_width));
                        }
                        lines.push(Line::from(Span::styled(
                            padded,
                            Style::default().add_modifier(Modifier::ITALIC),
                        )));
                    } else {
                        lines.push(Line::from(format!("  {}", display)));
                    }
                }
            }
            frame.render_widget(Paragraph::new(Text::from(lines)), inner);
        }
        if show_preview {
            let block = titled_block(" Preview ".to_string(), false);
            frame.render_widget(Paragraph::new(preview_text).block(block), chunks[1]);
        }
    }

