        let timeout = Duration::from_millis(self.config.cmd_timeout_millis as u64);
        // A process whose program has exited may still have its output
        // pipes held open by a background grandchild. Reading finishes in
        // a helper thread so the interface stays responsive meanwhile.
        if let Some(receiver) = self
            .running
            .as_ref()
            .and_then(|running| running.completion.as_ref())
        {
            match receiver.try_recv() {
                Ok(process) => {
                    let mut taken = self.running.take().expect("running process");
                    self.running_is_cache = false;
                    let command_raw = std::mem::take(&mut taken.command_raw);
                    let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                    self.complete_execution(kind, command_raw, Ok(process));
                }
                Err(mpsc::TryRecvError::Disconnected) => {
                    let mut taken = self.running.take().expect("running process");
                    self.running_is_cache = false;
                    let process = CompletedProcess {
                        status_success: taken.exited_success,
                        status_code: taken.exited_code,
                        stdout: String::new(),
                        stderr: String::new(),
                    };
                    let command_raw = std::mem::take(&mut taken.command_raw);
                    let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                    self.complete_execution(kind, command_raw, Ok(process));
                }
                Err(mpsc::TryRecvError::Empty) => {}
            }
            return;
        }
        if let Some(running) = self.running.as_mut() {
            let elapsed = running.started.elapsed();
            let child_exited = match running.child.as_mut().map(|child| child.try_wait()) {
                Some(Ok(Some(status))) => Some((status.success(), status.code().unwrap_or(-1))),
                Some(Ok(None)) => None,
                Some(Err(_)) => {
                    let mut taken = self.running.take().expect("running process");
                    self.running_is_cache = false;
                    let command_raw = std::mem::take(&mut taken.command_raw);
                    let kind = std::mem::replace(&mut taken.kind, ExecKind::Normal);
                    self.complete_execution(
                        kind,
                        command_raw,
                        Err(Output::Err("Unable to spawn command".to_string())),
                    );
                    return;
                }
                None => None,
            };
            if let Some((success, code)) = child_exited {
                running.exited_success = success;
                running.exited_code = code;
                running.child = None;
                let stdout_handle = running.stdout.take();
                let stderr_handle = running.stderr.take();
                let (sender, receiver) = mpsc::channel();
                running.completion = Some(receiver);
                std::thread::spawn(move || {
                    let mut stdout_thread = None;
                    if let Some(mut handle) = stdout_handle {
                        stdout_thread = Some(std::thread::spawn(move || {
                            let mut bytes = Vec::new();
                            let _ = handle.read_to_end(&mut bytes);
                            bytes
                        }));
                    }
                    let mut stderr_bytes = Vec::new();
                    if let Some(mut handle) = stderr_handle {
                        let _ = handle.read_to_end(&mut stderr_bytes);
                    }
                    let stdout_bytes = stdout_thread
                        .and_then(|thread| thread.join().ok())
                        .unwrap_or_default();
                    let process = CompletedProcess {
                        status_success: success,
                        status_code: code,
                        stdout: Self::bytes_to_string(stdout_bytes),
                        stderr: Self::bytes_to_string(stderr_bytes),
                    };
                    let _ = sender.send(process);
                });
                return;
            }
            if elapsed >= timeout {
